// TASK-69 quick-start dry run: load the claims screen, verify it renders and the
// live availability probe works, screenshot.
import { chromium } from 'playwright';

const base = process.env.BASE_URL ?? 'http://localhost:3000';
const out = process.env.OUT ?? '.ralph/screenshots/TASK-69-1-claims.png';

const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('console', (m) => {
  if (m.type() === 'error') errors.push(m.text());
});
page.on('pageerror', (e) => errors.push(String(e)));

await page.goto(base, { waitUntil: 'networkidle' });
await page.waitForTimeout(800);

const title = await page.title();
// The claims screen shows a callsign input + claim button (TASK-56).
const input = await page.locator('#callsign-input').count();
const button = await page.locator('#claim-button').count();
const status = await page.locator('#claims-status').count();

