  const cs = 'drift-dryrun-' + Date.now().toString(36).slice(-4);
  await page.locator('#callsign-input').fill(cs);
  await page.waitForTimeout(1500);
  statusText = (await page.locator('#claims-status').innerText().catch(() => 'none')).trim();
}

await page.screenshot({ path: out });
await browser.close();

