const fs = require('fs');
const path = require('path');
const files = [
  '/workspace/master/README.md',
  '/workspace/master/app/docs/architecture.md',
  '/workspace/master/app/docs/protocol.md',
  '/workspace/master/app/docs/ops.md',
  '/workspace/master/app/docs/contributing.md',
];
const problems = [];
for (const file of files) {
  const dir = path.dirname(file);
  const text = fs.readFileSync(file, 'utf8');
  const re = /\[[^\]]*\]\(([^)]+)\)/g;
  let m;
  while ((m = re.exec(text))) {
    let target = m[1].split(' ')[0];
    if (/^(https?:|mailto:|#)/.test(target)) continue;
    const hashIdx = target.indexOf('#');
    if (hashIdx >= 0) target = target.slice(0, hashIdx);
    if (!target) continue;
    const resolved = path.resolve(dir, target);
    if (!fs.existsSync(resolved)) {
      problems.push(`${path.relative('/workspace/master', file)} -> ${m[1]}  (${resolved})`);
    }
  }
}
if (problems.length === 0) console.log('ALL LINKS OK');
else { console.log('BROKEN LINKS:'); problems.forEach((p) => console.log('  ' + p)); }

